// The prize is the value of overlay_offset: the offset of compressed data
template <class T>
tribool PackMachBase<T>::canUnpack()
{
    unsigned const lc_seg = lc_seg_info[sizeof(Addr)>>3].segment_cmd;
    fi->seek(0, SEEK_SET);
    fi->readx(&mhdri, sizeof(mhdri));

